-- GameXS editorial overviews, part 6 (ps5_games.overview, migration 040).
--
-- Same format and rules as db/content/game_overviews.sql: original Persian copy
-- written for GameXS; facts checked against the IGDB data stored in ps5_games,
-- no text was copied from other sources.
--
-- Shape: {"intro", "suits": [..], "sections": [{"heading", "paragraphs": [..], "media"}]}
-- media = "trailer" | "screenshot:N" (1-based index into screenshot_ids); a key
-- the game has no asset for is skipped at render time.
--
-- Idempotent: re-running overwrites the overview of each listed slug and
-- touches nothing else. Apply with:
--   docker exec -i gamexs-postgres psql -U gamexs -d gamexs -v ON_ERROR_STOP=1 < db/content/game_overviews_part6.sql

UPDATE ps5_games g
SET overview = v.overview::jsonb
FROM (VALUES

('resident-evil-village', $j${
  "intro": "Resident Evil Village قسمت هشتم سری اصلی رزیدنت اویل و دنباله مستقیم Resident Evil 7 است که کپکام آن را در سال ۲۰۲۱ منتشر کرد. بازی همچنان اول‌شخص است و عناصر آشنای وحشت بقا مثل گشتن محیط، جمع‌کردن منابع و مدیریت مهمات را حفظ کرده، اما نسبت به قسمت قبل اکشن بیشتر، دشمنان پرتعدادتر و تنوع محیطی بسیار بیشتری دارد. فضای گوتیک یک روستای برفی در اروپای شرقی، این قسمت را به یکی از متمایزترین نسخه‌های سری تبدیل کرده است.",
  "suits": [
    "طرفداران وحشت بقا",
    "علاقه‌مندان اکشن اول‌شخص",
    "بازیکنان داستان‌محور"
  ],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "چند سال بعد از ماجراهای خانه بیکرها، ایتن وینترز و همسرش میا زندگی تازه‌ای را شروع کرده‌اند. این آرامش با ورود ناگهانی کریس ردفیلد به هم می‌ریزد و ایتن برای پیدا کردن جواب‌ها و نجات دخترش رز، به روستایی دورافتاده و مرموز کشیده می‌شود. روستا زیر سلطه «مادر میراندا» و چهار ارباب عجیب است که هرکدام قلمرو و سبک وحشت خودشان را دارند.",
        "معروف‌ترین چهره بازی، لیدی دیمیترسکو و قلعه باشکوهش است، اما خانه عروسک‌ها، دریاچه و کارخانه هر کدام حال‌وهوای کاملاً متفاوتی دارند و از تکراری شدن تجربه جلوگیری می‌کنند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "بازی ترکیبی از کاوش، معما و درگیری است. سلاح‌ها را می‌توانید ارتقا دهید، با شکار حیوانات و پخت غذا توانایی‌های دائمی بگیرید و از فروشنده‌ای به نام دوک وسایل و مهمات بخرید. روستا مثل یک مرکز عمل می‌کند و با پیشرفت داستان، مسیرهای تازه و رازهای پنهان در آن باز می‌شود.",
        "مدیریت منابع هنوز مهم است، اما برخلاف قسمت هفتم، لحظه‌های پرتنش با گروه‌هایی از دشمنان بیشتر پیش می‌آید و حس اکشن پررنگ‌تری دارد. پس از تمام کردن بخش داستانی، حالت Mercenaries برای امتیازگیری و تکرار مراحل در دسترس است."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر Resident Evil 7 را دوست داشتید یا دنبال یک تجربه وحشت با ریتم متعادل‌تر و اکشن بیشتر هستید، Village انتخاب خوبی است. داستان آن چند ساعت اول را کاملاً درگیرکننده می‌کند و طول بازی برای یک دور کامل حدوداً ده ساعت است. بازی کاملاً تک‌نفره است و برای شروع، آشنایی با قسمت قبل کمک می‌کند اما الزامی نیست."
      ],
      "media": "screenshot:7"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Resident Evil Village بازی تک‌نفره است و به اینترنت نیازی ندارد؛ بنابراین اکانت ظرفیت ۱ معمولاً ارزان‌ترین راه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر نمی‌خواهید کنسول را آفلاین نگه دارید، ظرفیت ۲ انعطاف بیشتری دارد. نسخه دیسکی هم برای کسانی که بعداً می‌خواهند بازی را بفروشند گزینه مناسبی است. قیمت هر روش را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('watch-dogs-legion', $j${
  "intro": "Watch Dogs Legion سومین قسمت سری Watch Dogs از یوبیسافت است که این بار اتفاقاتش در لندن آینده نزدیک می‌گذرد. شهری که زیر نظارت دائمی دوربین‌ها، پهپادها و یک شرکت امنیتی خصوصی به دولتی پلیسی تبدیل شده است. ایده مرکزی بازی این است که شخصیت اصلی ثابتی ندارد و تقریباً هر رهگذری را می‌توانید به گروه مقاومت دعوت کنید و با او بازی کنید.",
  "suits": [
    "علاقه‌مندان جهان‌باز",
    "طرفداران هک و مخفی‌کاری",
    "بازیکنانی که آزادی عمل می‌خواهند"
  ],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "پس از یک سلسله بمب‌گذاری در لندن، گروه هکری DedSec مقصر شناخته می‌شود و شهر به دست نیروهای امنیتی خصوصی و گروه‌های جنایتکار می‌افتد. شما باید شاخه لندنی DedSec را از نو بسازید، حقیقت پشت حملات را کشف کنید و شهر را به مردمش برگردانید.",
        "لندن بازی نسخه‌ای فشرده و آینده‌نگر از شهر واقعی است؛ از برج‌های شیشه‌ای تا محله‌های قدیمی و نشانه‌های آشنایی مثل پل‌ها و میدان‌های معروف. فضای سیاسی و طنز تلخ بازی در گفت‌وگوها و مأموریت‌های جانبی هم دیده می‌شود."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "هر شخصیت قابل‌بازی مهارت‌ها و ابزارهای خودش را دارد؛ یکی کارگر ساختمانی است و پهپاد باربری احضار می‌کند، دیگری مأمور سابق اطلاعاتی است و در مبارزه تن‌به‌تن قوی است. برای جذب هر نفر معمولاً باید مأموریت کوچکی برایش انجام دهید. اگر حالت مرگ دائمی را فعال کنید، از دست دادن یک عضو واقعاً به معنای رفتن همیشگی اوست.",
        "مأموریت‌ها را می‌توانید با هک دوربین‌ها و نفوذ از راه دور، مخفی‌کاری یا درگیری مستقیم پیش ببرید. عنکبوت‌های رباتیک، پهپادها و هک خودروها ابزارهای اصلی برای حل یک مأموریت بدون شلیک حتی یک گلوله‌اند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "این بازی برای کسانی جذاب است که از آزمایش و بداهه‌پردازی در یک جهان‌باز لذت می‌برند. اگر دنبال یک قهرمان پرشخصیت و داستان احساسی هستید، ممکن است شخصیت‌های قابل‌تعویض کمی بی‌روح به نظر برسند؛ در عوض تنوع رویکرد و گشت‌وگذار در لندن نقطه قوت اصلی بازی است. بازی بخش چندنفره و همکاری آنلاین هم دارد."
      ],
      "media": "screenshot:7"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "بخش داستانی Watch Dogs Legion تک‌نفره است، پس اگر فقط کمپین را می‌خواهید اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول آفلاین بماند. برای بخش آنلاین، ظرفیت ۲ یا ۳ لازم است و بازی آنلاین روی PS5 معمولاً به اشتراک PS Plus نیاز دارد. ظرفیت ۲ امکان بازی آنلاین و آفلاین را با هم می‌دهد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('collector-street-fighter-6-collectors-edition', $j${
  "intro": "Street Fighter 6 جدیدترین قسمت سری افسانه‌ای مبارزه‌ای کپکام است که در سال ۲۰۲۳ منتشر شد و با سه بخش اصلی، هم برای طرفداران قدیمی و هم برای تازه‌واردها برنامه دارد. علاوه بر مبارزه‌های کلاسیک یک‌به‌یک، بازی یک حالت داستانی جهان‌باز و یک فضای اجتماعی آنلاین هم دارد. این صفحه مربوط به نسخه کلکسیونی بازی است؛ محتوای دقیق بسته را از صفحه فروشنده بررسی کنید.",
  "suits": [
    "طرفداران بازی‌های مبارزه‌ای",
    "بازیکنان رقابتی",
    "دورهمی‌های دوستانه"
  ],
  "sections": [
    {
      "heading": "سه بخش اصلی بازی",
      "paragraphs": [
        "Fighting Ground قلب بازی است: مبارزه‌های آرکید، تمرین، حالت‌های آموزشی و بازی رودررو با یک نفر دیگر روی همان کنسول. World Tour حالت داستانی تک‌نفره است که در آن با آواتار ساخت خودتان در مترو سیتی و جاهای دیگر می‌گردید و از استادانی مثل ریو و چون‌لی سبک مبارزه یاد می‌گیرید.",
        "Battle Hub فضای آنلاین بازی است؛ جایی که آواتارها دور هم جمع می‌شوند، پشت دستگاه‌های آرکید با هم مبارزه می‌کنند و حتی نسخه‌های قدیمی بازی‌های کپکام را بازی می‌کنند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "سیستم Drive مهم‌ترین نوآوری مبارزه‌هاست؛ یک نوار انرژی که با آن می‌توانید ضربه‌ها را دفع کنید، حمله قدرتمند Drive Impact بزنید یا با Drive Rush سریع به حریف نزدیک شوید. مدیریت این نوار عمق تاکتیکی زیادی به هر راند می‌دهد.",
        "برای تازه‌کارها، کنترل Modern طراحی شده که حرکات ویژه را با یک دکمه انجام می‌دهد و ورود به بازی را بسیار راحت‌تر می‌کند. کنترل Classic هم برای کسانی است که دقت و گستره کامل حرکات را می‌خواهند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر اهل رقابت آنلاین هستید، Street Fighter 6 یکی از کامل‌ترین گزینه‌های امروز است. اگر بیشتر با دوستانتان کنار هم بازی می‌کنید یا می‌خواهید فقط حالت داستانی و آرکید را تجربه کنید، باز هم محتوای زیادی بدون اینترنت در اختیار دارید."
      ],
      "media": "screenshot:7"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "نسخه کلکسیونی معمولاً به‌صورت فیزیکی عرضه می‌شود و اقلام همراه آن ارزش جمع‌آوری دارند. اگر فقط خود بازی را می‌خواهید، روش‌های دیگر خرید را هم مقایسه کنید: برای بازی آفلاین و دونفره روی یک کنسول، اکانت ظرفیت ۱ ارزان‌تر است، اما برای مبارزه آنلاین و Battle Hub ظرفیت ۲ یا ۳ لازم است و بازی آنلاین روی PS5 معمولاً PS Plus می‌خواهد. قیمت‌ها را در جدول همین صفحه ببینید."
      ]
    }
  ]
}$j$),

('jurassic-world-evolution-3', $j${
  "intro": "Jurassic World Evolution 3 سومین قسمت سری شبیه‌سازی و مدیریت پارک دایناسورها از استودیو Frontier Developments است که در اکتبر ۲۰۲۵ منتشر شد. همان‌طور که از نامش پیداست، این بار هم باید پارکی پر از دایناسور بسازید، بازدیدکننده جذب کنید و مراقب باشید هیچ‌چیز از کنترل خارج نشود. مهم‌ترین تازگی این قسمت، اضافه شدن دایناسورهای نوجوان و پرورش چند نسل از آن‌هاست.",
  "suits": [
    "علاقه‌مندان بازی‌های مدیریتی",
    "طرفداران ژوراسیک پارک",
    "بازیکنان خلاق"
  ],
  "sections": [
    {
      "heading": "ایده اصلی بازی",
      "paragraphs": [
        "در این بازی مدیر یک پارک ژوراسیک هستید و در مکان‌های مختلفی در سراسر جهان، پارک‌های بزرگ ماقبل‌تاریخی طراحی و اداره می‌کنید. از ساختن محوطه‌ها و حصارها تا مسیرهای بازدیدکنندگان، رستوران‌ها و ایستگاه‌های امنیتی، همه بر عهده شماست.",
        "حال‌وهوای فیلم‌های ژوراسیک در طراحی ساختمان‌ها، صداها و رفتار دایناسورها حفظ شده و دیدن گله‌ای از دایناسورها که در محوطه‌ای که خودتان ساخته‌اید حرکت می‌کنند، یکی از لذت‌های اصلی بازی است."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی و تازه‌ها",
      "paragraphs": [
        "برای نخستین بار در سری، دایناسورها به‌صورت نوجوان هم دیده می‌شوند و می‌توانید چند نسل از آن‌ها را پرورش دهید. این موضوع به مدیریت محوطه‌ها و نیازهای حیوانات لایه تازه‌ای اضافه می‌کند؛ هر گونه نیازهای خاص خودش را در مورد فضا، غذا و هم‌نشینی دارد.",
        "در کنار مدیریت مالی و رضایت بازدیدکنندگان، باید برای فرار دایناسورها، طوفان‌ها و خرابی‌ها هم آماده باشید. ابزارهای ساخت‌وساز این قسمت گزینه‌های خلاقانه بیشتری برای شخصی‌سازی پارک فراهم کرده‌اند."
      ],
      "media": "screenshot:3"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر از بازی‌های مدیریتی مثل Planet Coaster یا نسخه‌های قبلی همین سری لذت برده‌اید، این بازی دقیقاً برای شماست. ریتم آن آرام‌تر از بازی‌های اکشن است و بیشتر به برنامه‌ریزی و صبر پاداش می‌دهد. برای بچه‌ها و نوجوان‌های علاقه‌مند به دایناسورها هم گزینه سالم و سرگرم‌کننده‌ای است."
      ],
      "media": "screenshot:6"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Jurassic World Evolution 3 بازی تک‌نفره است؛ بنابراین اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسول آنلاین باشد یا آپدیت‌ها را راحت دریافت کنید، ظرفیت ۲ انتخاب منعطف‌تری است. قیمت هر روش را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('shinobi-art-of-vengeance', $j${
  "intro": "Shinobi: Art of Vengeance بازگشت سری قدیمی و محبوب نینجاهای سگا است که در اوت ۲۰۲۵ منتشر شد. ساخت آن را استودیو فرانسوی Lizardcube بر عهده داشته؛ همان تیمی که پیش‌تر در احیای Wonder Boy و Streets of Rage 4 نقش داشت. نتیجه یک اکشن سکوبازی دوبعدی با طراحی دستی چشم‌نواز، مبارزه سریع و حال‌وهوای کلاسیک نینجایی است.",
  "suits": [
    "طرفداران اکشن دوبعدی",
    "علاقه‌مندان بازی‌های کلاسیک سگا",
    "بازیکنان مهارت‌محور"
  ],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "شما در نقش جو موساشی، استاد نینجای قبیله اوبورو، بازی می‌کنید. دشمنی قدرتمند به قبیله و دنیای او حمله کرده و جو با شمشیر افسانه‌ای اوبوروزوکی راهی سفری انتقامی می‌شود تا با هیولاها و نینجاهای دشمن بجنگد.",
        "مراحل بازی از مناطق شهری تا جنگل‌ها و مکان‌های اسرارآمیز را در بر می‌گیرند و هر کدام پالت رنگی و دشمنان مخصوص به خود را دارند. طراحی دستی شخصیت‌ها و پس‌زمینه‌ها حسی شبیه به یک انیمیشن متحرک به بازی داده است."
      ],
      "media": "screenshot:1"
    },
    {
