        "در این مسیر با «سایه‌ها»، جلوه‌های تاریک درون آدم‌ها، روبه‌رو می‌شوید و قدرتی پنهان به نام «پرسونا» را بیدار می‌کنید. داستان در کنار معما، درباره پذیرفتن خود واقعی و دوستی است."
