('saints-row-criminal-customs-edition', $j${
  "intro": "Saints Row نسخه بازراه‌اندازی‌شده سری جهان‌باز جنایی و طنزآمیز Saints Row است که در اوت ۲۰۲۲ منتشر شد. داستان این بار از صفر شروع می‌شود و گروهی از دوستان جوان را دنبال می‌کند که در شهری خیالی در جنوب‌غربی آمریکا، کسب‌وکار جنایی خودشان را راه می‌اندازند. نسخه Criminal Customs بازی اصلی را همراه با محتوای اضافه عرضه می‌کند که جزئیاتش را باید در صفحه فروشنده بررسی کنید.",
