('elden-ring-nightreign---seekers-edition', $j${
  "intro": "Elden Ring Nightreign یک بازی اکشن همکاری‌محور و مستقل در دنیای Elden Ring است که FromSoftware ساخته و بندای نامکو در مه ۲۰۲۵ منتشر کرده است. این بار به‌جای یک سفر طولانی، در دورهای فشرده و تکرارشونده همراه با دو بازیکن دیگر باید در سرزمینی که به‌مرور زیر یک شب مرگبار فرو می‌رود زنده بمانید. Seeker's Edition نسخه فیزیکی بازی در جعبه استیل‌بوک است که کد ارتقا به نسخه Digital Deluxe را هم دارد.",
