        "شخصیت‌های قابل‌بازی، که «نایت‌فارِر» نامیده می‌شوند، هر کدام توانایی‌ها و سبک مبارزه خاص خودشان را دارند و هماهنگی میانشان کلید پیروزی است."
      ]
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "مبارزه همان دقت و سختی آشنای Elden Ring را دارد، اما سریع‌تر شده است: شخصیت‌ها چابک‌ترند، از دیوارها بالا می‌روند و بدون آسیب از ارتفاع می‌پرند. نقشه هر دور با تغییرات و رویدادهای تصادفی متفاوت می‌شود تا هیچ دوری شبیه دور قبل نباشد.",
