('need-for-speed-payback', $j${
  "intro": "Need for Speed Payback یک بازی مسابقه‌ای جهان‌باز از استودیو Ghost Games و ناشر الکترونیک آرتز است که در سال ۲۰۱۷ منتشر شد. این قسمت با مأموریت‌های سرقت، نبردهای خودرویی پرریسک، تعقیب‌وگریز با پلیس و صحنه‌های نمایشی، حال‌وهوای یک فیلم اکشن هالیوودی را دارد و داستانی درباره خیانت و انتقام روایت می‌کند.",
